import React, { useState, useEffect } from "react";
import { Link, useParams } from "react-router-dom";
import SiteHeader from "../components/SiteHeader";
import SiteFooter from "../components/SiteFooter";

const API_BASE = process.env.REACT_APP_API_BASE || "";

// ============================================================
//  Simple Markdown Parser
//  فرمت‌های پشتیبانی شده:
//  ## متن  → تیتر
//  **متن** → بولد
//  - متن   → لیست
//  خط خالی → پاراگراف جدید
// ============================================================
function parseInline(text) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith("**") && part.endsWith("**")) {
      return <strong key={i} className="font-bold text-miko-dark">{part.slice(2, -2)}</strong>;
    }
    return <span key={i}>{part}</span>;
  });
}

function renderContent(content) {
  if (!content) return null;

  const blocks = content.split("\n\n");
  return blocks.map((block, i) => {
    const trimmed = block.trim();
    if (!trimmed) return null;

    // Heading: ## متن
    if (trimmed.startsWith("## ")) {
      return (
        <h3 key={i} className="text-xl font-bold text-miko-dark mt-8 mb-4">
          {parseInline(trimmed.slice(3))}
        </h3>
      );
    }

    // Heading: # متن
    if (trimmed.startsWith("# ") && !trimmed.startsWith("## ")) {
      return (
        <h2 key={i} className="text-2xl font-bold text-miko-dark mt-10 mb-4">
          {parseInline(trimmed.slice(2))}
        </h2>
      );
    }

    // List: - item
    if (trimmed.startsWith("- ")) {
      const items = trimmed.split("\n").filter(l => l.startsWith("- ")).map(l => l.slice(2));
      return (
        <ul key={i} className="my-4 space-y-2 pr-6">
          {items.map((item, j) => (
            <li key={j} className="text-miko-dark/80 leading-relaxed flex items-start gap-2">
              <span className="text-miko-rust mt-1 flex-shrink-0">●</span>
              <span>{parseInline(item)}</span>
            </li>
          ))}
        </ul>
      );
    }

    // Regular paragraph
    return (
      <p key={i} className="text-miko-dark/80 leading-loose mb-4 text-justify">
        {parseInline(trimmed)}
      </p>
    );
  });
}


export default function BlogPostPage() {
  const { slug } = useParams();
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    document.title = "بلاگ میکو — مقاله";
    window.scrollTo(0, 0);
    fetchPost();
  }, [slug]);

  const fetchPost = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE}/api/blog/${slug}`);
      if (!res.ok) throw new Error("Not found");
      const data = await res.json();
      setPost(data);
      document.title = `${data.title} — بلاگ میکو`;
    } catch (err) {
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const d = new Date(dateStr);
    return new Intl.DateTimeFormat("fa-IR", {
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(d);
  };

  if (loading) {
    return (
      <>
        <SiteHeader />
        <div className="min-h-screen bg-miko-cream flex items-center justify-center">
          <div className="inline-block w-12 h-12 border-4 border-miko-carrot/30 border-t-miko-rust rounded-full animate-spin"></div>
        </div>
        <SiteFooter />
      </>
    );
  }

  if (error || !post) {
    return (
      <>
        <SiteHeader />
        <div className="min-h-screen bg-miko-cream flex items-center justify-center pt-32 pb-20">
          <div className="text-center">
            <div className="text-6xl mb-4">🔍</div>
            <h1 className="text-2xl font-bold text-miko-dark mb-4">مقاله یافت نشد</h1>
            <p className="text-miko-dark/60 mb-6">مقاله‌ای که دنبالش هستید وجود ندارد یا حذف شده است.</p>
            <Link
              to="/blog"
              className="inline-block bg-miko-rust text-white font-bold px-6 py-3 rounded-xl hover:bg-miko-pumpkin transition-colors"
            >
              بازگشت به بلاگ
            </Link>
          </div>
        </div>
        <SiteFooter />
      </>
    );
  }

  return (
    <>
      <SiteHeader />
      <div className="min-h-screen bg-miko-cream" dir="rtl">
        {/* Hero */}
        <section className="bg-gradient-to-br from-ink-900 via-miko-rust to-miko-pumpkin text-miko-cream pt-32 pb-16 px-6">
          <div className="max-w-3xl mx-auto">
            <div className="flex items-center gap-3 mb-6">
              <Link
                to="/blog"
                className="text-sm text-miko-carrot hover:text-white transition-colors flex items-center gap-1"
              >
                ← بلاگ
              </Link>
              <span className="text-miko-carrot/50">/</span>
              <span className="text-sm bg-white/10 px-3 py-1 rounded-full text-miko-carrot">
                {post.category}
              </span>
            </div>

            <h1 className="text-3xl md:text-5xl font-black mb-6 leading-tight">
              {post.title}
            </h1>

            <p className="text-lg text-miko-carrot leading-relaxed mb-6">
              {post.excerpt}
            </p>

            <div className="flex items-center gap-4 text-sm text-miko-carrot/80">
              <span>📅 {formatDate(post.published_at)}</span>
              <span>👁 {post.views_count || 0} بازدید</span>
            </div>
          </div>
        </section>

        {/* Featured Image */}
        {post.featured_image && (
          <div className="max-w-3xl mx-auto -mt-8 px-6 relative z-10">
            <div className="rounded-2xl overflow-hidden shadow-xl">
              <img
                src={post.featured_image}
                alt={post.title}
                className="w-full h-64 md:h-96 object-cover"
              />
            </div>
          </div>
        )}

        {/* Content */}
        <article className="py-12 px-6">
          <div className="max-w-3xl mx-auto">
            <div className="bg-white rounded-2xl p-6 md:p-10 shadow-sm border border-miko-carrot/10">
              {renderContent(post.content)}
            </div>

            {/* Tags */}
            {post.tags && post.tags.length > 0 && (
              <div className="mt-8 flex flex-wrap gap-2">
                {post.tags.map((tag, i) => (
                  <span
                    key={i}
                    className="text-xs font-bold bg-miko-cream text-miko-rust px-3 py-1.5 rounded-lg border border-miko-carrot/20"
                  >
                    #{tag}
                  </span>
                ))}
              </div>
            )}
          </div>
        </article>

        {/* CTA */}
        <section className="py-16 px-6 bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white">
          <div className="max-w-3xl mx-auto text-center">
            <h2 className="text-2xl md:text-3xl font-bold mb-4">
              غذای اختصاصی برای سگ خود بساز
            </h2>
            <p className="text-white/90 mb-6">
              همین حالا اطلاعات سگت رو وارد کن و غذای تازه و سالم براش بساز
            </p>
            <Link
              to="/"
              className="inline-block bg-white text-miko-rust font-bold px-8 py-4 rounded-xl hover:bg-miko-cream transition-colors shadow-lg"
            >
              شروع سفارش
            </Link>
          </div>
        </section>

        {/* Back to Blog */}
        <div className="py-8 px-6 text-center bg-miko-cream">
          <Link
            to="/blog"
            className="inline-block text-miko-rust font-bold hover:underline"
          >
            ← بازگشت به همه مقالات
          </Link>
        </div>
      </div>
      <SiteFooter />
    </>
  );
}
